    private async Task RenderRejectedMaker(Beep.OilandGas.Client.App.CompanyClientContext company,IAccountingServiceClient client)
    {
        using var state=new CompanySalesReceivableWorkspaceState(company);state.AttachOwner(new object());var services=new ServiceCollection();services.AddLogging();services.AddMudServices();services.AddSingleton<IJSRuntime,APInvoiceFinancialHttpTests.NoBrowser>();services.AddSingleton<NavigationManager,APInvoiceFinancialHttpTests.Navigation>();services.AddSingleton(company);services.AddSingleton(state);services.AddSingleton(client);services.AddSingleton<AuthenticationStateProvider>(new Authentication{Actor="collector"});services.AddSingleton<IComponentActivator,MakerComponents>();await using var provider=services.BuildServiceProvider();await using var renderer=new HtmlRenderer(provider,provider.GetRequiredService<ILoggerFactory>());
        await renderer.Dispatcher.InvokeAsync(async()=>{
            var context=shared.Review.Current.Ledger;var root=await renderer.RenderComponentAsync<Beep.OilandGas.Web.Components.Workflow.SalesPaymentWorkbench>(ParameterView.FromDictionary(new Dictionary<string,object?>{{"ReceivableId",context.ReceivableId}}));var component=((MakerComponents)provider.GetRequiredService<IComponentActivator>()).Workbench!;component.GetType().GetField("_book",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(component,context.BookId);component.GetType().GetField("_currency",BindingFlags.NonPublic|BindingFlags.Instance)!.SetValue(component,context.CurrencyCode);component.GetType().GetMethod("StateHasChanged",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(component,null);await(Task)component.GetType().GetMethod("Load",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(component,null)!;component.GetType().GetMethod("StateHasChanged",BindingFlags.NonPublic|BindingFlags.Instance)!.Invoke(component,null);
            Assert.Equal("REJECTED",Assert.Single(state.PaymentSource!.Payments).Status);Assert.Equal(0,state.PaymentSource.UnreleasedProposedAmount);Assert.Contains("REJECTED",root.ToHtmlString());Assert.Contains("Return proposal to its maker",root.ToHtmlString());Assert.Contains("Original amount evidence issue",root.ToHtmlString());Assert.DoesNotContain("Record independent payment decision",root.ToHtmlString());Assert.DoesNotContain("Prepare reviewed payment proposal",root.ToHtmlString());Assert.DoesNotContain("COMMAND_JSON",root.ToHtmlString());
        });
    }
    [Fact]public async Task RenderedControllerRetainsExactDecisionThroughLostFollowupRecreationAndReadOnlyRecovery()
    {
        using var validation=CompanySalesInvoiceValidation.Enter();Reset();var p=shared.Base.Posting;var native=p.Reviewed.Draft.Native;var grants=new[]{"Accounting.View","Accounting.ReviewSalesPaymentSource","Accounting.ReviewSalesPayment","Accounting.RecordSalesPaymentDecision"};using var company=CompanyGLAccountHttpTests.Selected(actor:"controller",grants:grants);using var state=new CompanySalesReceivableWorkspaceState(company);state.AttachOwner(new object());var client=new Mock<IAccountingServiceClient>();var lost=true;var bodies=new List<string>();var context=shared.Review.Current.Ledger;
        client.Setup(value=>value.GetCompanySalesPaymentReviewAsync(shared.Draft.AR_PAYMENT_ID)).Returns(()=>p.AR.GetCompanySalesPaymentReviewAsync(context.Company,"controller",context.BindingRevision,shared.Draft.AR_PAYMENT_ID,p.Reviewed.Draft.Service,p.Guard,p.Field));client.Setup(value=>value.RecordCompanySalesPaymentReviewAsync(It.IsAny<CompanySalesPaymentReviewCommand>())).Returns((CompanySalesPaymentReviewCommand command)=>{bodies.Add(JsonSerializer.Serialize(command));return Record(command);});client.Setup(value=>value.GetCompanySalesPaymentReviewRecoveryAsync(shared.Draft.AR_PAYMENT_ID)).Returns(()=>lost?Task.FromException<CompanySalesPaymentReviewRecovery>(new InvalidOperationException("Lost native follow-up")):p.AR.GetCompanySalesPaymentReviewRecoveryAsync(context.Company,"controller",shared.Draft.AR_PAYMENT_ID,p.Guard,p.Field));client.Setup(value=>value.GetCompanySalesPaymentSourceAsync(context.ReceivableId,context.BookId,context.CurrencyCode)).Returns(()=>p.AR.GetCompanySalesPaymentSourceAsync(context.Company,"controller",context.BindingRevision,context.BookId,context.CurrencyCode,context.ReceivableId,p.Reviewed.Draft.Service,p.Guard,p.Field));
        var services=new ServiceCollection();services.AddLogging();services.AddMudServices();services.AddSingleton<IJSRuntime,APInvoiceFinancialHttpTests.NoBrowser>();services.AddSingleton<NavigationManager,APInvoiceFinancialHttpTests.Navigation>();services.AddSingleton(company);services.AddSingleton(state);services.AddSingleton<IAccountingServiceClient>(client.Object);services.AddSingleton<AuthenticationStateProvider,Authentication>();services.AddSingleton<IComponentActivator,Components>();await using var provider=services.BuildServiceProvider();await using var renderer=new HtmlRenderer(provider,provider.GetRequiredService<ILoggerFactory>());
        await renderer.Dispatcher.InvokeAsync(async()=>{
            var root=await renderer.RenderComponentAsync<Beep.OilandGas.Web.Components.Workflow.SalesPaymentReviewWorkbench>();var components=(Components)provider.GetRequiredService<IComponentActivator>();void Field(string name,object? value)=>components.Workbench!.GetType().GetField(name,BindingFlags.Instance|BindingFlags.NonPublic)!.SetValue(components.Workbench,value);void Render()=>components.Workbench!.GetType().GetMethod("StateHasChanged",BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(components.Workbench,null);async Task Action(string name){await(Task)components.Workbench!.GetType().GetMethod(name,BindingFlags.Instance|BindingFlags.NonPublic)!.Invoke(components.Workbench,null)!;Render();}
            Field("_id",shared.Draft.AR_PAYMENT_ID);Render();await Action("Load");Assert.Contains("Original statement evidence",root.ToHtmlString());await Action("Record");Assert.Equal(0,native.Writes);Assert.False(state.HasPendingPaymentReview);Field("_decision","APPROVE");Field("_financial","CONFIRMED");Field("_financialEvidence","Actual original amount evidence");Field("_receipt","CONFIRMED");Field("_receiptEvidence","Actual original receipt evidence");Field("_reason","Independent screen review");Render();await Action("Record");Assert.Equal(2,native.Writes);Assert.True(state.HasPendingPaymentReview);var original=JsonSerializer.Serialize(state.PendingPaymentReview);Assert.Contains("exact original independent decision is retained",root.ToHtmlString());Assert.False(state.CanPreparePayment);Assert.False(state.CanPostJournal);Assert.False(state.CanRecordReview);
            components.Workbench!.Dispose();root=await renderer.RenderComponentAsync<Beep.OilandGas.Web.Components.Workflow.SalesPaymentReviewWorkbench>();Assert.Equal(original,JsonSerializer.Serialize(state.PendingPaymentReview));lost=false;Assert.True(company.TrySelect(company.Clear(),"controller",new(context.Company,["ConfiguredCompanyRole"],["Accounting.View","Accounting.ReviewSalesPaymentSource"])));Field("_id",shared.Draft.AR_PAYMENT_ID);Render();await Action("Recover");Assert.False(state.HasPendingPaymentReview);Assert.NotNull(state.PaymentReviewRecovery!.Outcome);Assert.Equal(2,native.Writes);Assert.DoesNotContain("Record independent payment decision",root.ToHtmlString());Assert.Contains("APPROVED by controller",root.ToHtmlString());Assert.DoesNotContain("Reconcile original payment decision",root.ToHtmlString());
        });
    }
